label_replace(
  (
    label_replace(
      (
        (ordssrvs_status{namespace=~"$namespace",ordssrvs=~"$ordssrvs"} == 1)
        * on(namespace, ordssrvs) group_left(pool_health)
        label_replace(
          ordssrvs_pools_health{namespace=~"$namespace",ordssrvs=~"$ordssrvs"} == 1,
          "pool_health", "$1", "state", "(.*)"
        )
        * on(namespace, ordssrvs) group_left(total, ok, failed, pools)
        (
          label_join(
            (
              count_values by(namespace, ordssrvs)(
          "total",
          (ordssrvs_pool_total_count{namespace=~"$namespace",ordssrvs=~"$ordssrvs"} unless on(namespace, ordssrvs) (ordssrvs_pools_health{namespace=~"$namespace",ordssrvs=~"$ordssrvs",state="Disabled"} == 1))
        )
              * on(namespace, ordssrvs) group_left(ok)
              count_values by(namespace, ordssrvs)(
          "ok",
          (ordssrvs_pool_ok_count{namespace=~"$namespace",ordssrvs=~"$ordssrvs"} unless on(namespace, ordssrvs) (ordssrvs_pools_health{namespace=~"$namespace",ordssrvs=~"$ordssrvs",state="Disabled"} == 1))
        )
              * on(namespace, ordssrvs) group_left(failed)
              count_values by(namespace, ordssrvs)(
          "failed",
          (ordssrvs_pool_failed_count{namespace=~"$namespace",ordssrvs=~"$ordssrvs"} unless on(namespace, ordssrvs) (ordssrvs_pools_health{namespace=~"$namespace",ordssrvs=~"$ordssrvs",state="Disabled"} == 1))
        )
            ),
            "pools", "/", "ok", "total"
          )
          or on(namespace, ordssrvs)
          group by(namespace, ordssrvs)(
            ordssrvs_status{namespace=~"$namespace",ordssrvs=~"$ordssrvs"}
          )
        )
      ),
      "pool_health_core", "$1", "pool_health", "(.*)"
    )
  ),
  "pool_health_text", "$1", "pool_health", "(.*)"
